 body := jsonb_build_object('sender', jsonb_build_object('name','Krajevne skupnosti – Consigli delle frazioni','email',(select decrypted_secret from vault.decrypted_secrets where name='brevo_sender' limit 1)),
   'to', jsonb_build_array(jsonb_build_object('email','samuel.myphone@gmail.com')),
   'subject', $KS$[PROVA] Povzetek prijav krajanov – oktober 2026 / Riepilogo segnalazioni dei residenti – ottobre 2026$KS$, 'htmlContent', $KS$<div style="background:#eef2f5;padding:18px 0"><div style="max-width:760px;margin:0 auto;background:#fff;border-radius:10px;overflow:hidden;font-family:Arial,Helvetica,sans-serif;color:#1d2a35">
